/**
 * Типизация `meta` маршрутов. Правила доступа читает guard в `guards.ts`,
 * право — layout рабочего пространства, заголовок — шапка и `document.title`.
 */
import 'vue-router'
import type { Permission } from '@/entities/session'
import type { OnboardingStepKey } from '@/entities/organization'

declare module 'vue-router' {
  interface RouteMeta {
    /**
     * Требуемый контекст:
     * - `guest` — только без сессии (вход, регистрация, запрос письма сброса);
     * - `open` — с сессией и без неё (ссылки из писем: новый пароль, подтверждение почты);
     * - `session` — нужна сессия, организация не обязательна;
     * - `tenant` — нужны сессия и выбранная организация.
     */
    access?: 'guest' | 'open' | 'session' | 'tenant'
    /** Право роли, без которого показывается «Раздел недоступен». */
    permission?: Permission
    /** Название раздела для шапки и заголовка окна. */
    title?: string
    /**
     * Страница перенесена на дизайн v2: сама рисует контекст и заголовок, поэтому
     * верхняя полоса оболочки остаётся только на узких экранах (меню, бренд).
     */
    v2?: boolean
    /**
     * `radar` — выбранная оболочка C для Radar/risk, диалогов, аналитики, интеграций
     * и настроек: workspace внизу, аккаунт и настройки в хедере. Название варианта
     * не определяет активный пункт — его выбирает текущий маршрут. Доступ,
     * онбординг и платформенный Admin используют отдельные layouts.
     */
    shell?: 'radar'
    /** Шаг начала работы, который отображает страница (для индикатора шагов). */
    onboardingStep?: OnboardingStepKey
  }
}
